import { supabase } from '../lib/supabase'

/** sha별 학습 이력 집계 (원본 행 없이 카운트/시간만). */
export type LearningSummary = {
  sha: string
  cntTries: number
  cntPass: number
  cntFail: number
  cntTotal: number
  passRate: number
  duration: number
}

export type LearningHistoryInsert = {
  owner: string
  repo: string
  path: string
  sha: string
  line_no: number
  type: 'pass' | 'fail' | 'fin'
  duration: number
}

export type LearningHistoryRow = LearningHistoryInsert & {
  id: number
  user_id: string
  created_at: string
}

export async function addLearningHistories(
  items: LearningHistoryInsert[],
  userId?: string
): Promise<void> {
  const finalUserId = userId || (await supabase.auth.getUser()).data.user?.id
  if (!finalUserId) throw new Error('Not authenticated')

  const rows = items.map((item) => ({
    ...item,
    user_id: finalUserId,
  }))

  const { error } = await supabase.from('learning_histories').insert(rows)
  if (error) throw error
}

export async function getLearningHistoriesBySha(
  sha: string,
  userId?: string
): Promise<LearningHistoryRow[]> {
  let query = supabase
    .from('learning_histories')
    .select('*')
    .eq('sha', sha)
    .order('created_at', { ascending: true })

  if (userId) {
    query = query.eq('user_id', userId)
  }

  const { data, error } = await query

  if (error) throw error
  return data ?? []
}

/**
 * 여러 sha의 학습 이력 집계를 서버(RPC)에서 계산해 반환한다.
 * - 집계를 DB에서 수행하므로 PostgREST 기본 1000행 제한에 걸리지 않는다.
 * - POST(RPC)라 sha가 많아도 GET URL 길이 제한을 회피한다.
 * - 단일/복수 sha 모두 이 함수로 조회한다.
 */
export async function getLearningSummaries(shas: string[]): Promise<LearningSummary[]> {
  if (shas.length === 0) return []

  const { data, error } = await supabase.rpc('get_learning_summaries', {
    p_shas: shas,
  })
  if (error) throw error

  type SummaryRow = {
    sha: string
    cnt_tries: number
    cnt_pass: number
    cnt_fail: number
    duration: number
  }

  return ((data ?? []) as SummaryRow[]).map((row) => {
    const cntPass = Number(row.cnt_pass)
    const cntFail = Number(row.cnt_fail)
    const cntTotal = cntPass + cntFail
    return {
      sha: row.sha,
      cntTries: Number(row.cnt_tries),
      cntPass,
      cntFail,
      cntTotal,
      passRate: cntTotal > 0 ? (cntPass / cntTotal) * 100 : 0,
      duration: Number(row.duration),
    }
  })
}

export async function getLearningHistoriesByDirectory(
  owner: string,
  repo: string,
  path?: string,
  userId?: string
): Promise<LearningHistoryRow[]> {
  let query = supabase
    .from('learning_histories')
    .select('*')
    .eq('owner', owner)
    .eq('repo', repo)
    .eq('type', 'fin')
    .order('created_at', { ascending: true })

  if (path) {
    query = query.like('path', `${path}%`)
  }

  if (userId) {
    query = query.eq('user_id', userId)
  }

  const { data, error } = await query
  if (error) throw error
  return data ?? []
}

/**
 * owner/repo/path 디렉토리에 매칭되는 모든 학습 이력(pass/fail/fin)을 삭제한다.
 * fm:// 훈련 계획 삭제 시 연관 이력을 함께 정리하는 데 사용한다.
 */
export async function deleteLearningHistoriesByDirectory(
  owner: string,
  repo: string,
  path?: string,
  userId?: string
): Promise<void> {
  let query = supabase.from('learning_histories').delete().eq('owner', owner).eq('repo', repo)

  if (path) {
    query = query.like('path', `${path}%`)
  }

  if (userId) {
    query = query.eq('user_id', userId)
  }

  const { error } = await query
  if (error) throw error
}

/** deleteLearningHistoriesByDirectory 가 지우게 될 행 수. 삭제 확인 다이얼로그용. */
export async function countLearningHistoriesByDirectory(
  owner: string,
  repo: string,
  path?: string,
  userId?: string
): Promise<number> {
  let query = supabase
    .from('learning_histories')
    .select('id', { count: 'exact', head: true })
    .eq('owner', owner)
    .eq('repo', repo)

  if (path) {
    query = query.like('path', `${path}%`)
  }

  if (userId) {
    query = query.eq('user_id', userId)
  }

  const { count, error } = await query
  if (error) throw error
  return count ?? 0
}

export async function getAllLearningHistories(userId?: string): Promise<LearningHistoryRow[]> {
  let query = supabase
    .from('learning_histories')
    .select('*')
    .order('created_at', { ascending: false })

  if (userId) {
    query = query.eq('user_id', userId)
  }

  const { data, error } = await query
  if (error) throw error
  return data ?? []
}
